-- Import the categorized Koyas billing catalogue.
-- Source: Product_Master_Data.xlsx, re-audited on 2026-08-14.
-- Customer-facing names are normalized separately; the original billing and
-- print names remain in source_product_name/source_print_name for reconciliation.
-- The six unclear rows and seven ledger/service rows in the Review Queue are
-- intentionally not published. Rows without a valid sale price remain inactive,
-- and rows without opening stock remain unavailable until staff update inventory.

alter table public.products add column if not exists subcategory text not null default '';
alter table public.products add column if not exists brand text not null default '';
alter table public.products add column if not exists billing_group text;
alter table public.products add column if not exists source_row integer;
alter table public.products add column if not exists source_product_name text;
alter table public.products add column if not exists source_print_name text;
alter table public.products add column if not exists source_item_code text;
alter table public.products add column if not exists barcode text;
alter table public.products add column if not exists hsn_sac text;
alter table public.products add column if not exists gst_rate numeric(5, 2) not null default 0;
alter table public.products add column if not exists external_image_url text;
alter table public.products add column if not exists image_attribution text;
alter table public.products add column if not exists image_source_url text;

create unique index if not exists products_source_row_unique
on public.products(source_row) where source_row is not null;
create index if not exists products_barcode_idx
on public.products(barcode) where barcode is not null and barcode <> '';

-- Retain the old demo rows for order-history references, but hide them.
update public.products
set active = false, available = false
where id in (
  '20000000-0000-4000-8000-000000000001',
  '20000000-0000-4000-8000-000000000002',
  '20000000-0000-4000-8000-000000000003',
  '20000000-0000-4000-8000-000000000004',
  '20000000-0000-4000-8000-000000000005',
  '20000000-0000-4000-8000-000000000006',
  '20000000-0000-4000-8000-000000000007',
  '20000000-0000-4000-8000-000000000008',
  '20000000-0000-4000-8000-000000000009',
  '20000000-0000-4000-8000-000000000010'
);
update public.categories
set active = false
where id in (
  '10000000-0000-4000-8000-000000000001',
  '10000000-0000-4000-8000-000000000002',
  '10000000-0000-4000-8000-000000000003',
  '10000000-0000-4000-8000-000000000004',
  '10000000-0000-4000-8000-000000000005'
);

insert into public.categories (id, name, sort_order, active) values
  ('11000000-0000-4000-8000-000000000001'::uuid, 'Grocery & Staples', 1, true),
  ('11000000-0000-4000-8000-000000000002'::uuid, 'Breakfast & Ready-to-Cook', 2, true),
  ('11000000-0000-4000-8000-000000000003'::uuid, 'Snacks & Sweets', 3, true),
  ('11000000-0000-4000-8000-000000000004'::uuid, 'Beverages', 4, true),
  ('11000000-0000-4000-8000-000000000005'::uuid, 'Dairy & Frozen', 5, true),
  ('11000000-0000-4000-8000-000000000006'::uuid, 'Fresh Produce', 6, true),
  ('11000000-0000-4000-8000-000000000007'::uuid, 'Personal Care', 7, true),
  ('11000000-0000-4000-8000-000000000008'::uuid, 'Baby Care', 8, true),
  ('11000000-0000-4000-8000-000000000009'::uuid, 'Home Care', 9, true),
  ('11000000-0000-4000-8000-000000000010'::uuid, 'Health & Wellness', 10, true),
  ('11000000-0000-4000-8000-000000000011'::uuid, 'Pooja & Festive', 11, true),
  ('11000000-0000-4000-8000-000000000012'::uuid, 'Household & General', 12, true)
on conflict (id) do update set
  name = excluded.name,
  sort_order = excluded.sort_order,
  active = excluded.active,
  updated_at = now();

-- Make repeat application deterministic if the generated import is refreshed.
update public.products set active = false, available = false
where source_row is not null;

